// Helper function for delay
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Promisify this.runWorkflow
const runWorkflowPromise = (id, options) => {
  return new Promise((resolve, reject) => {
    this.runWorkflow(
      id,
      options,
      (res) => {
        console.log("成功结果：", res);
        resolve(res); // Resolve on success
      },
      (err) => {
        console.error("失败结果：", err);
        reject(err); // Reject on failure
      }
    );
  });
};

// Chain workflows with delays
let promiseChain = Promise.resolve();
let hasFailed = false;

workflow.forEach((item, index) => {
  if (!hasFailed) { // Only chain if no failure yet
    promiseChain = promiseChain
      .then(() => {
        if (index > 0) return delay(1000); // Add 1-second delay before each except the first
        return Promise.resolve(); // No delay before the first one
      })
      .then(() => {
        return runWorkflowPromise(item.id, { key: "value" });
      })
      .catch((err) => {
        hasFailed = true; // Mark failure
        console.log("done"); // Log "done" on first failure
        throw err; // Stop the chain
      });
  }
});

// Log "done" when all succeed
promiseChain
  .then(() => {
    if (!hasFailed) {
      alert("Successfully fetch all data")
      console.log("done"); // Log "done" if all succeeded
    }
  })
  .catch(() => {
    // Already logged "done" on failure, so no action needed here
  });

